import{z as i,x as n,o as t,c as d,q as s,j as r,D as B,d as e,s as A,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"向量化执行的深入","description":"","frontmatter":{"title":"向量化执行的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-vectorized-deep.md","filePath":"cs/qo-vectorized-deep.md","lastUpdated":1791063341000}'),p={name:"cs/qo-vectorized-deep.md"};function c(C,E,m,D,u,h){const o=n("Mermaid");return t(),d("div",null,[E[2]||(E[2]=s('<h1 id="向量化执行的深入" tabindex="-1">向量化执行的深入 <a class="header-anchor" href="#向量化执行的深入" aria-label="Permalink to &quot;向量化执行的深入&quot;">​</a></h1><div class="epigraph"><p>向量化不是「用了 SIMD 就快」，而是把每次决策摊到一批数据上：分支、虚调用、访存未命中，每样按批摊薄；摊不动的部分，批越大越亏。</p><footer>—— 据 Boncz, Zukowski and Nes, VLDB 2005；Leis et al., 2014；Kersten et al., PVLDB 2018 整理</footer></div><p><a href="/cs/qo-adaptive-execution">上一课</a>把决策点沿执行流铺开。主干 <a href="/cs/vectorized-execution">向量化执行</a> 钉了批粒度与选择向量，<a href="/cs/query-compilation">编译执行</a> 钉了代码生成，<a href="/cs/late-materialization">延迟物化</a> 钉了位置传递。本课深化三件事：宽度定多大、压缩数据上怎么直接算、多核下批从哪来，以及向量化与编译两条路线的混合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干给了「几百到几千行」的量级，工程要定数。太窄，解释税回潮；太宽，活跃向量集合（输入列、<span class="marginnote">选择向量就是一张「本批哪些行还活着」的下标清单：过滤后不搬数据、不压缩数组，只记录幸存行的位置，后续算子按这份清单继续算——省下的正是物化与搬运。</span>选择向量、哈希键）超出一二级缓存，中间数据自己成了内存压力，分支预测与 TLB 也开始抖。第二个缺口是压缩数据：解压后再过滤等于白付带宽——字典、游程、分块统计明明支持不解压就跳过或判伪，存储课的编码不能只在读取时用一次。第三个缺口在多核：静态把批分给工人，倾斜或速率不齐时，先做完的工人干等，并行名存实亡。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定宽：以「活跃向量的字节和落进一二级缓存」为准。例如宽 2048、每值八字节，一个列向量十六千字节，与一级缓存同量级；宽管道把活跃列数控制在个位数，多出的列按位置后取。压缩域执行：字典编码上先把谓词翻译成「码值谓词」——在字典项上比较，命中码集后再按位解压幸存行；游程段整段跳过或按段聚合；分块统计让整块数据不进 CPU（<a href="/cs/zone-maps">zone map</a> 口径）。morsel 调度：把扫描切成比向量更小的 morsel 放进队列，工人动态领取——负载均衡的粒度与向量化解耦：morsel 管「谁做」，向量管「怎么做」，同一管道可叠加。</p>',7)),(t(),r(l,null,{default:B(()=>[A(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MORSEL%5B%22morsel%20%E9%98%9F%E5%88%97%22%5D%20--%3E%20TAKE%5B%22%E5%B7%A5%E4%BA%BA%E5%8A%A8%E6%80%81%E9%A2%86%E5%8F%96%22%5D%0A%20%20TAKE%20--%3E%20SCAN%5B%22%E5%88%97%E5%90%91%E9%87%8F%E6%89%AB%E6%8F%8F%22%5D%0A%20%20SCAN%20--%3E%20COMP%5B%22%E5%8E%8B%E7%BC%A9%E5%9F%9F%E8%B0%93%E8%AF%8D%20%2F%20%E7%BB%9F%E8%AE%A1%E8%B7%B3%E8%BF%87%22%5D%0A%20%20COMP%20--%3E%20SV%5B%22%E9%80%89%E6%8B%A9%E5%90%91%E9%87%8F%22%5D%0A%20%20SV%20--%3E%20PROBE%5B%22%E5%90%91%E9%87%8F%E5%8C%96%E5%93%88%E5%B8%8C%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20PROBE%20--%3E%20OUT%5B%22%E6%89%B9%E8%BE%93%E5%87%BA%E7%BB%99%E4%B8%8A%E5%B1%82%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("与编译路线之争的对照口径：编译熔合算子、消灭调度，但生成代码膨胀，数据相关的分支在代码里仍是逐行判断；向量化保留解释结构、批摊开销，SIMD 显式可控。两者不互斥：编译生成批循环，或向量化内核按数据分布选专门化版本——后者正是上一课决策点谱系里的「算子内自适应」。代价模型跟着改口径：CPU 项拆成「每向量固定开销加每行变动开销」，否则第一课的悲剧重演，优化器与执行器各说各话。压缩域执行与"),a("a",{href:"/cs/column-compression"},"列压缩"),e("的编码选择是同一场谈判的两端：只有引擎认识的编码可短路，任意用户函数必须解压。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"DuckDB 的标准向量宽是 2048——八字节列一个向量恰十六千字节；ClickHouse 走另一极端，索引粒度默认 8192 行、面向整段序贯扫描。同一个「批」字，宽度差一个量级，管道形态完全不同。")],-1)),(t(),r(l,null,{default:B(()=>[A(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%90%91%E9%87%8F%E5%AE%BD%E5%BA%A6%E5%80%99%E9%80%89%22%5D%20--%3E%20Q1%7B%22%E5%A4%AA%E7%AA%84%EF%BC%9A%E5%87%A0%E5%8D%81%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20TAX%5B%22%E8%A7%A3%E9%87%8A%E7%A8%8E%E5%9B%9E%E6%BD%AE%EF%BC%9A%E8%B0%83%E7%94%A8%E4%B8%8E%E5%88%86%E6%94%AF%E6%91%8A%E4%B8%8D%E8%96%84%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20Q2%7B%22%E5%A4%AA%E5%AE%BD%EF%BC%9A%E6%95%B0%E4%B8%87%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20CACHE%5B%22%E6%B4%BB%E8%B7%83%E5%90%91%E9%87%8F%E8%B6%85%E4%B8%80%E4%BA%8C%E7%BA%A7%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20PRESS%5B%22%E8%AE%BF%E5%AD%98%E4%B8%8E%20TLB%20%E6%88%90%E7%93%B6%E9%A2%88%22%5D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20FIT%5B%22%E6%B4%BB%E8%B7%83%E5%AD%97%E8%8A%82%E5%92%8C%E8%90%BD%E5%9C%A8%E7%BC%93%E5%AD%98%E5%86%85%22%5D%0A%20%20FIT%20--%3E%20SWEET%5B%22%E4%B8%A4%E5%8D%83%E4%B8%8A%E4%B8%8B%EF%BC%9A%E6%89%B9%E6%91%8A%E7%A8%8E%E4%B8%8E%E7%BC%93%E5%AD%98%E9%A9%BB%E7%95%99%E5%85%BC%E5%BE%97%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p><span class="marginnote">这张图回答的问题是：批宽到底怎么定——它是「解释税随宽度摊薄」与「活跃数据随宽度膨胀」两条曲线的交点附近，不是越大越好；数字实例：宽 2048、每值八字节时一个列向量就是 \\(2048 \\times 8\\) 字节 \\(= 16\\) KB，恰好与一级缓存同量级。</span></p><p><span class="marginnote">初学者容易以为向量化与编译是「二选一」的路线之争；实际上主流系统常是混合体：编译生成批循环骨架，向量化内核负责批内计算——两者分歧只在「谁来熔合算子、谁来摊销开销」，不在「用不用 SIMD」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>GPU 与协处理器不进本课。OLTP 窄行短查询批摊税不划算，主干已钉；本课的领域仍是分析型长管道。压缩域执行的上限是编码的表达力：复杂谓词最终仍要解压兜底，短路是优化不是语义——改写结果必须与解压后逐行求值同指称。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宽度由活跃向量的缓存驻留决定，两千上下是常见落点。</li><li>压缩域执行先算码值谓词再解压幸存行，带宽留在存储层。</li><li>morsel 管负载均衡，向量管指令效率，两者正交可叠加。</li><li>向量化与编译不互斥；代价模型的 CPU 项要按批重写。</li><li>出处：Boncz, Zukowski and Nes, 2005；Leis et al., 2014；Kersten et al., 2018。</li></ul>',6))])}const T=i(p,[["render",c]]);export{f as __pageData,T as default};
